import dlartg = require( './index' );


// TESTS //

// The function returns void...
{
	const F = new Float64Array( 1 );
	const G = new Float64Array( 1 );
	const C = new Float64Array( 1 );
	const S = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( F, G, C, S, R ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not a Float64Array...
{
	const G = new Float64Array( 1 );
	const C = new Float64Array( 1 );
	const S = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( '5', G, C, S, R ); // $ExpectError
	dlartg( 5, G, C, S, R ); // $ExpectError
	dlartg( true, G, C, S, R ); // $ExpectError
	dlartg( false, G, C, S, R ); // $ExpectError
	dlartg( null, G, C, S, R ); // $ExpectError
	dlartg( void 0, G, C, S, R ); // $ExpectError
	dlartg( [], G, C, S, R ); // $ExpectError
	dlartg( {}, G, C, S, R ); // $ExpectError
	dlartg( ( x: number ): number => x, G, C, S, R ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Float64Array...
{
	const F = new Float64Array( 1 );
	const C = new Float64Array( 1 );
	const S = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg( F, '5', C, S, R ); // $ExpectError
	dlartg( F, 5, C, S, R ); // $ExpectError
	dlartg( F, true, C, S, R ); // $ExpectError
	dlartg( F, false, C, S, R ); // $ExpectError
	dlartg( F, null, C, S, R ); // $ExpectError
	dlartg( F, void 0, C, S, R ); // $ExpectError
	dlartg( F, [], C, S, R ); // $ExpectError
	dlartg( F, {}, C, S, R ); // $ExpectError
	dlartg( F, ( x: number ): number => x, C, S, R ); // $ExpectError
}

