// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const F = new Float64Array( 1 );
	const G = new Float64Array( 1 );
	const C = new Float64Array( 1 );
	const S = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg(); // $ExpectError
	dlartg( F ); // $ExpectError
	dlartg( F, G ); // $ExpectError
	dlartg( F, G, C ); // $ExpectError
	dlartg( F, G, C, S ); // $ExpectError
	dlartg( F, G, C, S, R, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns void...
{
	const F = new Float64Array( 1 );
	const G = new Float64Array( 1 );
	const C = new Float64Array( 1 );
	const S = new Float64Array( 1 );
	const R = new Float64Array( 1 );

	dlartg.ndarray( F, 0, G, 0, C, 0, S, 0, R, 0 ); // $ExpectType void
}

