	const R = new Float64Array( 1 );

	dlartg.ndarray(); // $ExpectError
	dlartg.ndarray( F ); // $ExpectError
	dlartg.ndarray( F, 0 ); // $ExpectError
	dlartg.ndarray( F, 0, G ); // $ExpectError
	dlartg.ndarray( F, 0, G, 0 ); // $ExpectError
	dlartg.ndarray( F, 0, G, 0, C ); // $ExpectError
